from pysat.solvers import Glucose3

def solve():
    solver = Glucose3()
    n = 41
    k = 4
    # Variables 1 to n
    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + (k - 1) * d <= n:
                # All same color (all True or all False)
                # Not all True
                solver.add_clause([- (a + i * d) for i in range(k)])
                # Not all False
                solver.add_clause([a + i * d for i in range(k)])

    if solver.solve():
        print("SAT")
    else:
        print("UNSAT")

solve()
